import{_ as o,C as r,o as t,c as n,a2 as a,b as d,w as i,a as c,E as l,a3 as u}from"./chunks/framework.ChIlRNAd.js";const v=JSON.parse('{"title":"Sécurité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/technical/security.md","filePath":"fr/technical/security.md"}'),h={name:"fr/technical/security.md"};function p(m,e,b,f,g,q){const s=r("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="securite" tabindex="-1">Sécurité <a class="header-anchor" href="#securite" aria-label="Permalink to &quot;Sécurité&quot;">​</a></h1><p>Vue d&#39;ensemble des mesures de sécurité implémentées dans Nid.</p><hr><h2 id="authentification" tabindex="-1">Authentification <a class="header-anchor" href="#authentification" aria-label="Permalink to &quot;Authentification&quot;">​</a></h2><h3 id="jwt-httponly" tabindex="-1">JWT httpOnly <a class="header-anchor" href="#jwt-httponly" aria-label="Permalink to &quot;JWT httpOnly&quot;">​</a></h3><p>Le JWT (HS256) est stocké dans le <strong>cookie httpOnly</strong> <code>token</code>, inaccessible au JavaScript côté client. Cela protège contre les attaques XSS qui tenteraient de voler le token.</p><ul><li><strong>Un seul token</strong> : durée de vie <code>JWT_EXPIRY</code> (24 h par défaut), identique à celle du cookie</li><li><strong>Cookie</strong> : <code>httpOnly</code>, <code>sameSite: strict</code>, <code>secure</code> en production</li><li><code>POST /api/auth/refresh</code> ré-émet un token pour une session encore valide ; le frontend ne le fait pas automatiquement</li><li>Le frontend ne stocke aucun token (ni <code>localStorage</code>, ni URL : les flux SSE utilisent aussi le cookie)</li></ul><h3 id="blacklist-jwt-redis" tabindex="-1">Blacklist JWT Redis <a class="header-anchor" href="#blacklist-jwt-redis" aria-label="Permalink to &quot;Blacklist JWT Redis&quot;">​</a></h3><p>Au logout, le token est ajouté à une blacklist Redis. Le middleware <code>authenticate</code> vérifie cette blacklist à chaque requête, permettant l&#39;<strong>invalidation immédiate</strong> d&#39;un token compromis. Il refuse aussi (401) un utilisateur désactivé (<code>users.is_active = false</code>).</p><h3 id="hashage-des-mots-de-passe" tabindex="-1">Hashage des mots de passe <a class="header-anchor" href="#hashage-des-mots-de-passe" aria-label="Permalink to &quot;Hashage des mots de passe&quot;">​</a></h3><p>Les mots de passe sont hashés avec <strong>bcrypt</strong> (12 rounds). Un hash factice est calculé même quand l&#39;utilisateur n&#39;existe pas, ce qui empêche l&#39;énumération de comptes par timing attack.</p><h3 id="rate-limiting" tabindex="-1">Rate limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate limiting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Route</th><th>Limite</th></tr></thead><tbody><tr><td><code>POST /api/auth/register</code></td><td>3 requêtes / minute</td></tr><tr><td><code>POST /api/auth/login</code></td><td>5 requêtes / minute</td></tr><tr><td>Routes générales</td><td>100 requêtes / minute / IP</td></tr></tbody></table><h3 id="_2fa-totp" tabindex="-1">2FA TOTP <a class="header-anchor" href="#_2fa-totp" aria-label="Permalink to &quot;2FA TOTP&quot;">​</a></h3><p>L&#39;authentification à deux facteurs est optionnelle pour les comptes locaux. Elle utilise <strong>TOTP</strong> (RFC 6238) via <code>otplib</code>, avec génération de QR code pour la configuration.</p><h3 id="passkeys-webauthn" tabindex="-1">Passkeys (WebAuthn) <a class="header-anchor" href="#passkeys-webauthn" aria-label="Permalink to &quot;Passkeys (WebAuthn)&quot;">​</a></h3><p>Connexion sans mot de passe via <code>@simplewebauthn/server</code>, liée au site du frontend (<code>FRONTEND_URL</code>). La vérification utilisateur (code ou biométrie de l&#39;appareil) est obligatoire, donc la passkey vaut à elle seule deux facteurs : la 2FA TOTP n&#39;est pas redemandée. Seule la clé publique est stockée ; les challenges sont à usage unique (Redis, 5 min). Voir <a href="./api/auth.html#passkeys-webauthn">API › Passkeys</a>.</p><h3 id="sso-multi-providers" tabindex="-1">SSO multi-providers <a class="header-anchor" href="#sso-multi-providers" aria-label="Permalink to &quot;SSO multi-providers&quot;">​</a></h3><p>Le Social Login utilise la librairie <strong>Arctic</strong> avec échange de code OAuth2 côté serveur. Les tokens sociaux ne transitent jamais par le frontend.</p><p>Providers supportés : Google, Microsoft, Discord, Facebook, LinkedIn, Keycloak (les providers sans identifiants configurés sont désactivés). Le <code>state</code> et le code verifier PKCE sont conservés 5 min dans Redis. Seul un email vérifié par le provider peut être rattaché à un compte existant ou correspondre à <code>ADMIN_EMAIL</code>.</p><h3 id="tokens-gmail" tabindex="-1">Tokens Gmail <a class="header-anchor" href="#tokens-gmail" aria-label="Permalink to &quot;Tokens Gmail&quot;">​</a></h3><p>Les tokens OAuth2 Gmail (<code>access_token</code>, <code>refresh_token</code>) sont stockés <strong>en clair</strong> dans <code>mail_accounts</code> : la protection repose sur l&#39;accès à la base. À la déconnexion d&#39;un compte, ils sont mis à <code>NULL</code>.</p><hr><h2 id="autorisation" tabindex="-1">Autorisation <a class="header-anchor" href="#autorisation" aria-label="Permalink to &quot;Autorisation&quot;">​</a></h2><h3 id="isolation-multi-utilisateurs" tabindex="-1">Isolation multi-utilisateurs <a class="header-anchor" href="#isolation-multi-utilisateurs" aria-label="Permalink to &quot;Isolation multi-utilisateurs&quot;">​</a></h3><p>Deux décorateurs Fastify assurent l&#39;isolation des données :</p><ul><li><strong><code>requireAccountOwnership</code></strong> — Vérifie que le paramètre <code>:accountId</code> appartient à l&#39;utilisateur authentifié. Appliqué sur toutes les routes Gmail, archive, dashboard et règles.</li><li><strong><code>requireAdmin</code></strong> — Vérifie que <code>role === &#39;admin&#39;</code> dans le JWT. Appliqué sur les routes admin, intégrité et la configuration de la corbeille archives.</li></ul><p>Les routes les combinent via <code>authPresets(app)</code> (<code>auth</code>, <code>accountAuth</code>, <code>adminAuth</code>). Les routes sans <code>:accountId</code> (jobs, notifications, règles de rétention…) filtrent sur <code>user_id = request.user.sub</code>.</p>',28)),(t(),d(u,null,{default:i(()=>[l(s,{id:"mermaid-143",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20REQ%5BRequ%C3%AAte%20HTTP%5D%20--%3E%20AUTH%5Bauthenticate%5D%0A%20%20%20%20AUTH%20--%3E%20OWN%7BrequireAccountOwnership%7D%0A%20%20%20%20OWN%20--%3E%7COK%7C%20HANDLER%5BHandler%20route%5D%0A%20%20%20%20OWN%20--%3E%7C403%7C%20REJECT%5BAcc%C3%A8s%20refus%C3%A9%5D%0A%20%20%20%20%0A%20%20%20%20AUTH%20--%3E%20ADM%7BrequireAdmin%7D%0A%20%20%20%20ADM%20--%3E%7COK%7C%20ADMIN_HANDLER%5BHandler%20admin%5D%0A%20%20%20%20ADM%20--%3E%7C403%7C%20REJECT%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="roles" tabindex="-1">Rôles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Rôles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rôle</th><th>Accès</th></tr></thead><tbody><tr><td><code>user</code></td><td>Ses propres données (mails, archives, règles, jobs, notifications)</td></tr><tr><td><code>admin</code></td><td>Idem + page administration (utilisateurs, jobs globaux, quotas, intégrité)</td></tr></tbody></table><hr><h2 id="validation-des-entrees" tabindex="-1">Validation des entrées <a class="header-anchor" href="#validation-des-entrees" aria-label="Permalink to &quot;Validation des entrées&quot;">​</a></h2><p>Toutes les entrées utilisateur sont validées avec <strong>Zod</strong> :</p><ul><li>Schémas stricts sur les corps de requête, query params et paramètres d&#39;URL</li><li>Types TypeScript inférés depuis les schémas Zod</li><li>Les champs inconnus sont ignorés (comportement par défaut de Zod) ; une erreur de validation renvoie <code>400 { error, details }</code></li></ul><p>La recherche full-text utilise <code>plainto_tsquery</code> (et non <code>to_tsquery</code>), ce qui neutralise les opérateurs de requête et protège contre l&#39;injection d&#39;opérateurs PostgreSQL.</p><hr><h2 id="chiffrement-des-archives" tabindex="-1">Chiffrement des archives <a class="header-anchor" href="#chiffrement-des-archives" aria-label="Permalink to &quot;Chiffrement des archives&quot;">​</a></h2><p>Les archives EML peuvent être chiffrées au repos sur le NAS :</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead><tbody><tr><td>Algorithme</td><td>AES-256-GCM (confidentialité + intégrité)</td></tr><tr><td>Dérivation de clé</td><td>PBKDF2 (SHA-512, 100 000 itérations)</td></tr><tr><td>Salt</td><td>32 octets aléatoires par fichier</td></tr><tr><td>IV</td><td>12 octets aléatoires par fichier</td></tr><tr><td>Stockage passphrase</td><td>Hash scrypt en base — jamais la passphrase elle-même</td></tr></tbody></table><h3 id="format-binaire" tabindex="-1">Format binaire <a class="header-anchor" href="#format-binaire" aria-label="Permalink to &quot;Format binaire&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GMENC01 (7 B) | SALT (32 B) | IV (12 B) | AUTH_TAG (16 B) | CIPHERTEXT</span></span></code></pre></div><ul><li>Magic bytes <code>GMENC01</code> pour la détection des fichiers chiffrés</li><li>Déchiffrement à la volée sans fichier temporaire</li><li>Idempotence : les fichiers déjà chiffrés sont ignorés</li></ul><hr><h2 id="securite-reseau" tabindex="-1">Sécurité réseau <a class="header-anchor" href="#securite-reseau" aria-label="Permalink to &quot;Sécurité réseau&quot;">​</a></h2><h3 id="production" tabindex="-1">Production <a class="header-anchor" href="#production" aria-label="Permalink to &quot;Production&quot;">​</a></h3><ul><li>Le conteneur <code>nid</code> n&#39;expose que le port 3000 (Nginx), configurable via <code>APP_PORT</code></li><li>CORS configuré sur <code>FRONTEND_URL</code> uniquement</li></ul><div class="warning custom-block"><p class="custom-block-title">PostgreSQL et Redis exposés par défaut</p><p>Le <code>docker-compose.yml</code> fourni publie <code>5432</code> (PostgreSQL) et <code>6379</code> (Redis) sur l&#39;hôte, pour les outils de dev. Supprimez ces blocs <code>ports:</code> en production si ces services ne doivent pas être joignables hors du réseau Docker <code>nid-net</code>.</p></div><h3 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h3><p>Les webhooks de type <code>generic</code> incluent un header <code>X-Webhook-Signature</code> (<code>sha256=&lt;HMAC-SHA256 du payload&gt;</code>), permettant au destinataire de vérifier l&#39;authenticité de la requête. Une authentification Basic optionnelle est possible (<code>auth_user</code>, <code>auth_password</code>).</p><p>Protection SSRF : les URL qui résolvent vers une adresse loopback, privée, link-local (métadonnées cloud), CGNAT ou non spécifiée sont refusées, sauf si <code>WEBHOOK_ALLOW_PRIVATE_NETWORKS=true</code> (ntfy, Home Assistant sur le LAN…).</p><h3 id="configuration-automatique-imap" tabindex="-1">Configuration automatique IMAP <a class="header-anchor" href="#configuration-automatique-imap" aria-label="Permalink to &quot;Configuration automatique IMAP&quot;">​</a></h3><p><code>GET /api/auth/imap/autoconfig</code> contacte <code>autoconfig.thunderbird.net</code> et <code>autoconfig.&lt;domaine de l&#39;adresse saisie&gt;</code> : le même garde (<code>utils/net.ts</code>, <code>ipaddr.js</code>) s&#39;applique, <strong>sans contournement</strong> (un hôte non public n&#39;est jamais contacté, quelle que soit la configuration), sans suivre de redirection, 3 s et 64 Ko au plus par requête, 20 requêtes/min. Reste, comme pour les webhooks, la fenêtre de DNS rebinding entre la résolution et la requête.</p><h3 id="pieces-jointes-analysees" tabindex="-1">Pièces jointes analysées <a class="header-anchor" href="#pieces-jointes-analysees" aria-label="Permalink to &quot;Pièces jointes analysées&quot;">​</a></h3><p>Le texte des PDF (pdf.js via <code>unpdf</code>, sans <code>eval</code>) et des DOCX est extrait dans le processus Node, borné à 20 Mo, 100 pages, 50 000 caractères et 10 s ; un DOCX dont <code>word/document.xml</code> annonce plus de 20 Mo n&#39;est pas décompressé (zip bomb). Un fichier illisible ou hostile donne un texte vide, jamais une erreur d&#39;archivage.</p><h3 id="contenu-des-mails" tabindex="-1">Contenu des mails <a class="header-anchor" href="#contenu-des-mails" aria-label="Permalink to &quot;Contenu des mails&quot;">​</a></h3><p>Les images distantes des mails sont bloquées par défaut dans le lecteur (<code>notification_preferences.remote_images = &#39;block&#39;</code>), ce qui évite les pixels de suivi.</p><hr><h2 id="securite-des-fichiers" tabindex="-1">Sécurité des fichiers <a class="header-anchor" href="#securite-des-fichiers" aria-label="Permalink to &quot;Sécurité des fichiers&quot;">​</a></h2><ul><li>Les noms de fichiers dans les headers <code>Content-Disposition</code> sont sanitisés</li><li>Les chemins de fichiers sont validés pour empêcher les traversées de répertoire</li><li>Les fichiers EML sont identifiés par UUID, pas par des chemins utilisateur</li><li>Les liens de partage d&#39;archive (<code>/shared/:token</code>) utilisent un token aléatoire unique, avec date d&#39;expiration et nombre d&#39;accès maximal optionnel ; les liens expirés sont nettoyés toutes les heures</li></ul><h2 id="secrets-dans-les-jobs" tabindex="-1">Secrets dans les jobs <a class="header-anchor" href="#secrets-dans-les-jobs" aria-label="Permalink to &quot;Secrets dans les jobs&quot;">​</a></h2><p>Les identifiants passés à un job (phrase secrète de chiffrement, mot de passe IMAP) sont retirés de la copie du payload stockée dans la table <code>jobs</code> (lisible via <code>/api/jobs</code> et l&#39;admin). Dans Redis, ces jobs sont supprimés dès leur fin ; ils ne peuvent pas être relancés via <code>POST /api/jobs/:jobId/retry</code>.</p><hr><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Toutes les actions sensibles sont tracées dans le journal d&#39;audit :</p><table tabindex="0"><thead><tr><th>Catégorie</th><th>Actions tracées</th></tr></thead><tbody><tr><td>Authentification</td><td>Connexion (mot de passe, SSO Google, social), inscription, activation / désactivation de la 2FA</td></tr><tr><td>Comptes Gmail</td><td>Connexion, déconnexion d&#39;un compte</td></tr><tr><td>Règles</td><td>Création (dont depuis un template), modification, suppression, exécution</td></tr><tr><td>Opérations bulk</td><td>Corbeille, suppression, archivage, libellés ; suppression des mails d&#39;un expéditeur</td></tr><tr><td>Archives</td><td>Lancement d&#39;un archivage, export ZIP</td></tr><tr><td>Administration</td><td>Modification d&#39;utilisateur, vidage de la corbeille archives</td></tr></tbody></table><p>Chaque entrée inclut l&#39;adresse IP de la requête pour la traçabilité.</p><hr><h2 id="securite-des-conteneurs-docker" tabindex="-1">Sécurité des conteneurs Docker <a class="header-anchor" href="#securite-des-conteneurs-docker" aria-label="Permalink to &quot;Sécurité des conteneurs Docker&quot;">​</a></h2><h3 id="images-de-base" tabindex="-1">Images de base <a class="header-anchor" href="#images-de-base" aria-label="Permalink to &quot;Images de base&quot;">​</a></h3><ul><li><strong>Images Alpine</strong> — Utilisation systématique de variantes Alpine pour réduire la surface d&#39;attaque (moins de binaires, moins de CVE potentielles)</li><li><strong>Mises à jour</strong> — <code>apk upgrade --no-cache</code> en production pour appliquer les correctifs de sécurité</li></ul><h3 id="build-multi-stage" tabindex="-1">Build multi-stage <a class="header-anchor" href="#build-multi-stage" aria-label="Permalink to &quot;Build multi-stage&quot;">​</a></h3><p>Le <code>Dockerfile</code> racine (image unifiée nginx + Node) utilise un <strong>build multi-stage</strong> (frontend-builder, backend-builder → deps → runner) pour que l&#39;image finale ne contienne :</p><ul><li>Ni le code source</li><li>Ni les devDependencies</li><li>Ni les outils de build (npm, corepack, yarn)</li></ul><h3 id="utilisateur-non-root" tabindex="-1">Utilisateur non-root <a class="header-anchor" href="#utilisateur-non-root" aria-label="Permalink to &quot;Utilisateur non-root&quot;">​</a></h3><p>Les processus tournent avec un <strong>utilisateur non-root</strong> (<code>appuser:appgroup</code>, UID/GID 1001) : <code>entrypoint.sh</code> démarre en root pour corriger les permissions des volumes, puis bascule via <code>su-exec</code>. Le code et la config nginx appartiennent à root (lecture seule pour <code>appuser</code>) ; seul <code>/archives</code> est accessible en écriture. Cela limite l&#39;impact d&#39;une éventuelle compromission du processus Node.js.</p><h3 id="dockerignore" tabindex="-1"><code>.dockerignore</code> <a class="header-anchor" href="#dockerignore" aria-label="Permalink to &quot;`.dockerignore`&quot;">​</a></h3><p>Des fichiers <code>.dockerignore</code> empêchent la copie de fichiers sensibles dans le contexte de build :</p><ul><li><code>.env</code>, <code>.env.*</code>, <code>*.pem</code>, <code>*.key</code> — Variables d&#39;environnement et secrets</li><li><code>.git</code> — Historique Git</li><li><code>node_modules</code>, <code>coverage</code>, <code>dist</code> — Artefacts de build</li><li><code>volumes/</code> — Données utilisateur</li></ul><h3 id="reseau-interne" tabindex="-1">Réseau interne <a class="header-anchor" href="#reseau-interne" aria-label="Permalink to &quot;Réseau interne&quot;">​</a></h3><p>Les services communiquent via le réseau Docker <code>nid-net</code>. Les conteneurs tournent avec <code>no-new-privileges</code> et <code>cap_drop: ALL</code> (seules les capacités nécessaires sont rajoutées). Voir l&#39;avertissement ci-dessus sur les ports PostgreSQL et Redis publiés par défaut.</p><h3 id="ignore-scripts" tabindex="-1"><code>--ignore-scripts</code> <a class="header-anchor" href="#ignore-scripts" aria-label="Permalink to &quot;`--ignore-scripts`&quot;">​</a></h3><p>Les commandes <code>npm ci</code> de production utilisent <code>--ignore-scripts</code> pour empêcher l&#39;exécution de scripts <code>postinstall</code> potentiellement malveillants dans les dépendances.</p>',54))])}const A=o(h,[["render",p]]);export{v as __pageData,A as default};
